div><div class="cm-line"><span class="tok-comment">--</span><span class="tok-comment"> Question: Different Income Bands mein Risk Weighting ka distribution </span></div><div class="cm-line"><span class="tok-comment">--</span><span class="tok-comment">           aur average financial metrics kya hain?</span></div><div class="cm-line cm-activeLine"><span class="tok-comment">--</span><span class="tok-comment"> =====================================================</span></div><div class="cm-line"><span class="tok-keyword">SELECT</span> </div><div class="cm-line">    <span class="tok-keyword">CASE</span> </div><div class="cm-line">        <span class="tok-keyword">WHEN</span> <span class="tok-string">`</span><span class="tok-string">Estimated Income</span><span class="tok-string">`</span> <span class="tok-operator">&lt;</span> <span class="tok-number">100000</span> <span class="tok-keyword">THEN</span> <span class="tok-string">'</span><span class="tok-string">Low</span><span class="tok-string">'</span></div><div class="cm-line">        <span class="tok-keyword">WHEN</span> <span class="tok-string">`</span><span class="tok-string">Estimated Income</span><span class="tok-string">`</span> <span class="tok-keyword">BETWEEN</span> <span class="tok-number">100000</span> <span class="tok-keyword">AND</span> <span class="tok-number">300000</span> <span class="tok-keyword">THEN</span> <span class="tok-string">'</span><span class="tok-string">Middle</span><span class="tok-string">'</span></div><div class="cm-line">        <span class="tok-keyword">ELSE</span> <span class="tok-string">'</span><span class="tok-string">High</span><span class="tok-string">'</span></div><div class="cm-line">    <span class="tok-keyword">END</span> <span class="tok-keyword">AS</span> Income_Band,</div><div class="cm-line">    <span class="tok-string">`</span><span class="tok-string">Risk Weighting</span><span class="tok-string">`</span>,</div><div class="cm-line">    <span class="tok-function">COUNT</span>(<span class="tok-operator">*</span>) <span class="tok-keyword">AS</span> Total_Customers,</div><div class="cm-line">    <span class="tok-function">ROUND</span>(<span class="tok-function">AVG</span>(<span class="tok-string">`</span><span class="tok-string">Estimated Income</span><span class="tok-string">`</span>), <span class="tok-number">0</span>) <span class="tok-keyword">AS</span> Avg_Income,</div><div class="cm-line">    <span class="tok-function">ROUND</span>(<span class="tok-function">AVG</span>(<span class="tok-string">`</span><span class="tok-string">Credit Card Balance</span><span class="tok-string">`</span>), <span class="tok-number">0</span>) <span class="tok-keyword">AS</span> Avg_CC_Balance,</div><div class="cm-line">    <span class="tok-function">ROUND</span>(<span class="tok-function">AVG</span>(<span class="tok-string">`</span><span class="tok-string">Bank Deposits</span><span class="tok-string">`</span>), <span class="tok-number">0</span>) <span class="tok-keyword">AS</span> Avg_Deposits,</div><div class="cm-line">    <span class="tok-function">ROUND</span>(<span class="tok-function">AVG</span>(<span class="tok-string">`</span><span class="tok-string">Bank Loans</span><span class="tok-string">`</span>), <span class="tok-number">0</span>) <span class="tok-keyword">AS</span> Avg_Loans</div><div class="cm-line"><span class="tok-keyword">FROM</span> customer</div><div class="cm-line"><span class="tok-keyword">GROUP BY</span> Income_Band, <span class="tok-string">`</span><span class="tok-string">Risk Weighting</span><span class="tok-string">`</span></div><div class="cm-line"><span class="tok-keyword">ORDER BY</span> Income_Band, <span class="tok-string">`</span><span class="tok-string">Risk Weighting</span><span class="tok-string">`</span>;</div><div class="cm-line"><br></div><div class="cm-line"><br></div><div class="cm-line"><span class="tok-comment">--</span><span class="tok-comment"> =====================================================</span></di